   where c.tipo = 'checklist' and c.status <> 'concluida'),
mud as (
  select id, ck, v, p, dt, dur,
    nullif(ck->>'agendadoPara', '')::timestamp is distinct from dt muda_data,
    coalesce(ck->>'projetista', '') <> p muda_proj,
    coalesce(ck->>'etapa', '') <> 'agendado' muda_etapa,
    coalesce((ck->>'duracaoMin')::int, 120) <> dur muda_dur
  from alvo),
upd as (
  update public.chamados c set
    status = case when c.status = 'aberta' then 'tratativa' else c.status end,
    tratativa = jsonb_set(c.tratativa, '{checklist}', m.ck || jsonb_build_object('etapa', 'agendado', 'agendadoPara', to_char(m.dt, 'YYYY-MM-DD"T"HH24:MI:SS'),
      'projetista', m.p, 'duracaoMin', m.dur, 'retornarEm', null, 'encaixe', false, 'encaixeCom', null)
      || case when m.muda_data then jsonb_build_object('confirmacao', '') else '{}'::jsonb end)
  from mud m where c.id = m.id and (m.muda_data or m.muda_proj or m.muda_etapa or m.muda_dur)
  returning m.*),
h as (
  insert into public.historico (chamado_id, quem_id, quem_nome, texto)
  select id, null, 'Sistema', '📅 Ajustado conforme a agenda oficial: ' || to_char(dt, 'DD/MM/YYYY HH24:MI') || ' até ' || to_char(dt + make_interval(mins => dur), 'HH24:MI') || ' com ' || p
         || case when muda_etapa then ' (passou para agendado)' else '' end from upd returning 1)
select (select count(*) from o) vendas_print, (select count(*) from alvo) no_360, (select count(*) from upd) alterados,
  (select count(*) from upd where muda_data) datas, (select count(*) from upd where muda_proj) projs, (select count(*) from upd where muda_etapa) viraram_agendado,
  (select count(*) from h) hist,
  (select string_agg(v, ',' order by v) from o where not exists (select 1 from alvo where alvo.v = o.v)) fora_360;
